const KEY='bsk-cmdb-workspace-v1';let revision=0,saving=false,typeFilter='',legacyData=null;let db,seed,view='inventory',query='',statusFilter='',criticalFilter='',sourceFilter='',page=1,allFields=false,room='Salle IT 1',rackQuery='',lastFocus,toastTimer,importDraft,rackUnitSelection={};
let currentRole='reader',currentUser=null,qualityFilter='';
const adminActions=new Set(['add-host','edit-record','add-record','add-rack','add-room','edit-rack','placement','rack-assign','rack-unit-select','rack-selection-add-host','remove-record','remove-placement','confirm-remove','app-add','app-edit','app-delete','app-delete-confirm','delete-host','delete-host-confirm','delete-rack','delete-rack-confirm','legacy','legacy-import','backup','restore','import','apply-import','template','history']);
