function openHost(id){const h=hostById(id);if(!h)return;const r=primary(h);modal(h.server,`<div class="host-hero">${pill(r.status||'Unknown')}${pill(r.criticality||'Unknown')}${pill(typeLabel(h.type))}<span class="pill">${h.records.length} application records</span><span class="pill">${h.connections.length} network links</span></div>${!h.records.length?'<div class="source-banner">This device appears in the room layout. No matching CMDB record was found; missing fields have not been invented.</div>':''}<div class="detail-section" style="border:0;padding:0"><div class="record-title"><h3>${h.type==='virtual'?'VMware location':'Physical placement'}</h3>${h.type==='physical'?btn('Assign rack / unit','placement',h.id,'','edit'):btn('Edit host type','edit-record',h.id+':0','','edit')}</div>${h.type==='virtual'?`<dl class="detail-grid">${detail('vCenter',h.vmware.vcenter)}${detail('VMware cluster',h.vmware.cluster)}${detail('ESXi host',h.vmware.esxiHost)}${detail('VM name',h.vmware.vmName)}</dl>`:h.placements.length?h.placements.map((p,i)=>{const rack=rackById(p.rackId);return `<div class="equip-row" style="margin-top:12px"><div><button class="link-button" data-action="rack" data-id="${esc(p.rackId)}">${esc(rack?.name||'Unknown rack')} · U${p.unit}${p.height>1?'–'+(p.unit+p.height-1):''}</button><small>${esc(roomDisplay(rack?.room))} · ${esc(rack?.aisle)} · ${p.height}U</small></div><button ${!canAdmin()?'hidden':''} class="icon-button" data-action="remove-placement" data-id="${h.id}:${i}" aria-label="Remove placement ${i+1}">${icon('x')}</button></div>`}).join(''):'<p class="note-paragraph">No rack position is currently linked. Location fields from the host record appear below.</p>'}</div>${h.records.map((rec,i)=>`<section class="detail-section"><div class="record-title"><h3>Application record ${i+1}${rec.application?' · '+esc(rec.application):''}</h3><div class="actions">${btn('Edit','edit-record',h.id+':'+i,'','edit')}${btn('Remove','remove-record',h.id+':'+i,'','trash')}</div></div><dl class="detail-grid">${fields.map(([k,l])=>detail(l,rec[k])).join('')}</dl></section>`).join('')}<section class="detail-section"><div class="record-title"><h3>Application relationships</h3>${btn('Add application record','add-record',h.id,'','plus')}</div><p class="note-paragraph">Multiple CMDB rows are retained here so each application, owner, and availability arrangement remains visible.</p></section>${h.connections.length?`<section class="detail-section"><h3>LAN / SAN connections · ${h.connections.length}</h3>${h.connections.map((c,i)=>`<details><summary style="cursor:pointer;padding:12px 0;font-size:12px;color:#597492">${i+1}. ${esc(c.fields.Switch||c.source)} · Port ${esc(displayValue(c.fields['Port SW'])||'—')}</summary><dl class="detail-grid">${Object.entries(c.fields).map(([k,v])=>detail(k,v)).join('')}</dl></details>`).join('')}</section>`:''}`,`${btn('Delete host','delete-host',h.id,'danger','trash')}<div class="actions">${btn('Close','close')}${btn('Edit host record','edit-record',h.id+':0','primary','edit')}</div>`,'HOST / DEVICE DETAILS')}
function selectedRackUnits(rackId){return [...new Set(rackUnitSelection[rackId]||[])].sort((a,b)=>a-b)}
function selectionRange(rackId){const units=selectedRackUnits(rackId);return units.length?{unit:units[0],height:units[units.length-1]-units[0]+1}:null}
function openRack(id){const r=rackById(id);if(!r)return;const s=rackStats(r),selected=new Set(selectedRackUnits(id));const overlaps=s.list.filter((a,i)=>s.list.some((b,j)=>i!==j&&a.p.unit<b.p.unit+b.p.height&&b.p.unit<a.p.unit+a.p.height));const unitRows=Array.from({length:r.units},(_,i)=>{const unit=r.units-i,free=!s.used.has(unit),picked=selected.has(unit);const cell=canAdmin()&&free?`<button class="unit-empty unit-selectable ${picked?'selected':''}" data-action="rack-unit-select" data-id="${esc(r.id+':'+unit)}" style="grid-row:${i+1};grid-column:2" aria-label="Select ${esc(r.name)} unit ${unit}" title="Select U${unit}">U${unit}</button>`:`<span class="unit-empty ${free?'':'occupied'}" style="grid-row:${i+1};grid-column:2"></span>`;return `<span class="unit-number" style="grid-row:${i+1};grid-column:1">${unit}</span>${cell}`}).join('');const range=selectionRange(id),selectionOk=range&&selectedRackUnits(id).length===range.height&&!placementList(id).some(({p})=>range.unit<p.unit+p.height&&p.unit<range.unit+range.height);const selectionText=range?`Selected U${range.unit}${range.height>1?'–'+(range.unit+range.height-1):''} · ${range.height}U`:'Click free rack units to prepare a host placement.';modal(r.name,`<div class="host-hero"><span class="pill">${esc(roomDisplay(r.room))}</span><span class="pill">${esc(r.aisle)}</span><span class="pill">${r.units}U</span></div>${r.notes?`<div class="warning">${esc(r.notes)}</div>`:''}${overlaps.length?'<div class="warning">Multiple devices have overlapping rack positions. All are retained in the equipment list. Verify these placements before editing.</div>':''}<div class="rack-modal"><div><div class="eyebrow">FRONT ELEVATION · TOP TO BOTTOM</div><div class="elevation" style="grid-template-rows:repeat(${r.units},20px)">${unitRows}${s.list.map(({h,p})=>`<button class="device" data-action="host" data-id="${h.id}" style="grid-row:${Math.max(1,r.units-p.unit-p.height+2)} / span ${p.height}" title="${esc(h.server)} · U${p.unit}–${p.unit+p.height-1}" aria-label="Open host ${esc(h.server)} at U${p.unit}">${esc(h.server)}</button>`).join('')}</div>${canAdmin()?`<div class="rack-selection-panel"><span>${esc(selectionText)}</span>${selectionOk?btn('Add host to selected units','rack-selection-add-host',id,'primary','plus'):''}</div>`:''}</div><div><div class="mini-statline"><span><strong>${s.count}</strong> devices</span><span><strong>${s.used.size}U</strong> mapped</span><span><strong>${s.pct}%</strong> documented</span></div><h3 style="font-size:13px">Equipment in this rack</h3><p style="font-size:11px;margin:10px 0 18px">${canAdmin()?'Click one or more free rack units to prefill a new physical host.':'Select a host in the elevation or in this list to view all information.'}</p><div class="rack-equip-list">${s.list.sort((a,b)=>b.p.unit-a.p.unit).map(({h,p})=>`<div class="equip-row"><div>${hostLink(h)}<small>${esc(primary(h).application||p.label||'Layout equipment')}</small></div><span class="pill">U${p.unit}${p.height>1?'–'+(p.unit+p.height-1):''}</span></div>`).join('')||'<div class="empty">No equipment is documented here yet.</div>'}</div><dl class="detail-grid" style="grid-template-columns:1fr 1fr;margin-top:25px">${detail('RJ45 ports',r.rj45)}${detail('Fibre ports',r.fibre)}</dl></div></div>`,`<div class="actions">${btn('Delete rack','delete-rack',id,'danger','trash')}${btn('Edit rack','edit-rack',id,'','edit')}${btn('Assign existing host','rack-assign',id,'','plus')}${selectionOk?btn('Add host to selected units','rack-selection-add-host',id,'primary','plus'):''}</div>`,'RACK INVENTORY')}
function typeLabel(type){return type==='physical'?'Physical':type==='virtual'?'Virtual · VMware':'Needs classification'}
function addRoomForm(){
 modal('Add computer room',`<form id="roomForm" novalidate><div class="form-error" id="formError" role="alert"></div><div class="form-grid"><label class="wide">Computer room name *<input name="name" maxlength="150" placeholder="e.g. Computer Room 3"></label></div></form>`,`<div class="actions">${btn('Cancel','close')}<button class="btn primary" type="submit" form="roomForm">Save computer room</button></div>`,'COMPUTER ROOM ADMINISTRATION');
 $('#roomForm').onsubmit=async e=>{e.preventDefault();const name=String(new FormData(e.target).get('name')||'').trim();const box=$('#formError');if(!name){box.textContent='Enter a computer room name.';return}if(roomNames().some(n=>roomDisplay(n).toLowerCase()===roomDisplay(name).toLowerCase())){box.textContent='This computer room already exists.';return}if(await transact(()=>{db.rooms=[...roomNames(),name]},'Computer room saved','Added computer room',name)){room=name;closeModal();location.hash='room';render()}};
}
function recordForm(id,index=0,preset={}){
 const h=id?hostById(id):null,rec=h?.records[index]||{};
 const currentPlacement=h?.placements[0]||(preset.rackId?{rackId:preset.rackId,unit:preset.unit||'',height:preset.height||''}:null);
 const placedRack=currentPlacement&&rackById(currentPlacement.rackId);
 const rooms=roomNames();
 const selectedRoom=placedRack?.room||(rooms.includes(rec.location)?rec.location:rooms.includes(room)?room:rooms[0]||'');
 const roomLabel=name=>{const m=String(name).match(/^Salle IT\s*(\d+)$/i);return m?'Computer Room '+m[1]:name};
 const inputs=fields.map(([k,l])=>{
  if(k==='application')return `<label class="wide">Application<select name="applicationId"><option value="">No application assigned</option>${db.applications.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(a=>`<option value="${esc(a.id)}" ${a.id===rec.applicationId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>`;
  return `<label class="${['location','rack','rackUnit','bay'].includes(k)?'physical-field'+(k==='location'?' location-field':''):''}">${esc(l)}${k==='server'?' *':''}<input name="${k}" value="${esc(rec[k]||(k==='server'?h?.server||'':''))}" maxlength="1500" ${h&&k==='server'?'readonly':''} ${k==='status'?'list="statuses"':''} ${k==='criticality'?'list="criticals"':''}></label>`;
 }).join('');
 const placementFields=`<section id="rackPlacementFields" class="wide"><h3>Rack position</h3><p class="subtle">Select a rack and specify the bottom unit and the number of units this host occupies. Leave the rack blank when its position is unknown.</p><div class="form-grid">
 <label class="wide">Computer room location *<select name="placementRoom">${rooms.map(r=>`<option value="${esc(r)}" ${r===selectedRoom?'selected':''}>${esc(roomLabel(r))}</option>`).join('')}</select></label>
 <label class="wide">Rack<select name="placementRackId"><option value="">No confirmed rack position</option></select></label>
 <label>Starting rack unit (bottom U)<input name="placementUnit" type="number" min="1" max="60" step="1" value="${currentPlacement?.unit||''}" placeholder="e.g. 12"></label>
 <label>Rack units occupied<input name="placementHeight" type="number" min="1" max="60" step="1" value="${currentPlacement?.height||''}" placeholder="e.g. 2"></label></div>
 ${h?.placements.length>1?'<p class="subtle">Additional placements are retained. Manage them from the host details.</p>':''}</section>`;
 modal(h?'Edit host / application record':'Add a host',`<form id="recordForm" novalidate><div id="formError" class="form-error" role="alert" tabindex="-1"></div><div class="form-grid"><label class="wide">Host type *<select name="hostType"><option value="">Choose physical or virtual…</option><option value="physical" ${(h?.type==='physical'||preset.rackId)?'selected':''}>Physical — computer room</option><option value="virtual" ${h?.type==='virtual'?'selected':''}>Virtual — VMware</option></select></label><p class="wide subtle">${esc(preset.rackId?'Rack position preselected from the rack design. Complete the host details and save.':h?.typeBasis||'Physical equipment uses rack positions. Virtual machines use VMware locations.')}</p>${placementFields}<div id="vmwareFields" class="wide form-grid">${[['vcenter','vCenter'],['cluster','VMware cluster'],['esxiHost','ESXi host'],['vmName','VM name']].map(([k,l])=>`<label>${l}<input name="vm_${k}" value="${esc(h?.vmware?.[k]||'')}" maxlength="1500"></label>`).join('')}</div>${inputs}<details class="wide"><summary class="link-button">Add an application to the catalog</summary><div class="inline-create"><input id="quickAppName" placeholder="New application name" maxlength="1500" aria-label="New application name"><button type="button" class="btn" id="quickAppSave">Add application</button></div></details></div><datalist id="statuses">${['Prod','QA','Planned','Retired','Decommissioned'].map(v=>`<option value="${v}">`).join('')}</datalist><datalist id="criticals">${['Very High','High','Medium','Low'].map(v=>`<option value="${v}">`).join('')}</datalist></form>`,`<div class="actions">${btn('Cancel',h?'host':'close',h?.id||'')}<button class="btn primary" type="submit" form="recordForm">Save host</button></div>`,'INVENTORY ADMINISTRATION');
 const form=$('#recordForm'),typeSelect=form.elements.hostType,roomSelect=form.elements.placementRoom,rackSelect=form.elements.placementRackId;
 const showError=message=>{const box=$('#formError');if(box){box.textContent=message;box.focus()}else toast(message)};
 const updateRacks=selected=>{
  rackSelect.innerHTML='<option value="">No confirmed rack position</option>'+db.racks.filter(r=>r.room===roomSelect.value).map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.aisle)} / ${esc(r.name)} (${r.units}U)</option>`).join('');
  const enabled=!!rackSelect.value;
  form.elements.placementUnit.disabled=!enabled;form.elements.placementHeight.disabled=!enabled;
 };
 roomSelect.onchange=()=>updateRacks('');
 rackSelect.onchange=()=>updateRacks(rackSelect.value);
 const changeType=()=>{const virtual=typeSelect.value==='virtual',physical=typeSelect.value==='physical';$('#vmwareFields').hidden=!virtual;$('#rackPlacementFields').hidden=!physical;$$('.physical-field').forEach(e=>e.hidden=!physical||e.classList.contains('location-field'))};
 typeSelect.onchange=changeType;updateRacks(currentPlacement?.rackId||'');changeType();
 $('#quickAppSave').onclick=async()=>{
  const name=$('#quickAppName').value.trim();if(!name){showError('Enter an application name.');return}
  const existing=db.applications.find(a=>CmdbModel.appKey(a.name)===CmdbModel.appKey(name));if(existing){form.elements.applicationId.value=existing.id;toast('Selected the existing application.');return}
  const app={id:newId(),name,owner:'',description:'',source:'Added by administrator'};
  if(await transact(()=>db.applications.push(app),'Application added','Added application',name)){form.elements.applicationId.add(new Option(name,app.id));form.elements.applicationId.value=app.id;$('#quickAppName').value=''}
 };
 form.onsubmit=async e=>{
  e.preventDefault();$('#formError').textContent='';
  try{
  const values=Object.fromEntries(new FormData(form)),server=String(values.server||'').trim();
  if(!server){showError('Enter a host name.');return}
  if(!['physical','virtual'].includes(values.hostType)){showError('Choose physical or virtual host type.');return}
  if(values.hostType==='physical'&&!rooms.includes(roomSelect.value)){showError('Choose a computer room location.');return}
  if(db.hosts.some(x=>x.server.toLowerCase()===server.toLowerCase()&&x.id!==id)){showError('This host already exists. Add an application record to it instead.');return}
  if(values.hostType==='virtual'&&h?.placements.length){showError('Remove this host’s physical rack placements before changing it to virtual.');return}
  const app=values.applicationId?db.applications.find(a=>a.id===values.applicationId):null;
  if(values.applicationId&&!app){showError('Choose a valid application from the catalog.');return}
  let rack=null,u=0,height=0;
  if(values.hostType==='physical'&&rackSelect.value){
   rack=rackById(rackSelect.value);u=Number(form.elements.placementUnit.value);height=Number(form.elements.placementHeight.value);
   if(!rack||rack.room!==roomSelect.value){showError('Choose a rack in the selected computer room.');return}
   if(!Number.isInteger(u)||!Number.isInteger(height)||u<1||height<1||u+height-1>rack.units){showError(`Enter a starting unit and units occupied within the rack’s 1–${rack.units}U capacity.`);return}
   if(placementList(rack.id).some(({h:other,p})=>!(h&&other.id===h.id&&p===currentPlacement)&&u<p.unit+p.height&&p.unit<u+height)){showError('These rack units already contain a documented device. Choose another position.');return}
  }else if(values.hostType==='physical'&&currentPlacement){showError('To remove an existing placement, use Remove placement in the host details.');return}
  const record=Object.fromEntries(fields.map(([k])=>[k,k==='application'?app?.name||'':(values[k]||'').trim()]));record.applicationId=app?.id||'';
  if(values.hostType==='virtual')for(const key of ['rack','rackUnit','bay'])record[key]='';
  if(values.hostType==='physical'&&(!h||['Added by administrator','Added by owner'].includes(rec.source)))record.location=roomSelect.value;
  if(rack&&(!h||['Added by administrator','Added by owner'].includes(rec.source))){record.location=rack.room;record.rack=rack.name;record.rackUnit=String(u)}
  const hid=id||newId();
  const ok=await transact(()=>{if(values.hostType==='physical')db.rooms=roomNames();let target=hostById(hid);if(!target){target={id:hid,server,records:[],placements:[],connections:[],sample:false};db.hosts.unshift(target)}
   target.type=values.hostType;target.typeBasis='Classified by administrator';
   target.vmware=Object.fromEntries(['vcenter','cluster','esxiHost','vmName'].map(k=>[k,(values['vm_'+k]||'').trim()]));
   if(target.type==='virtual'&&!target.vmware.vmName)target.vmware.vmName=server;
   if(rack){const placement={rackId:rack.id,unit:u,height,label:server,source:currentPlacement?.source||'Rack assignment',positionBasis:'Manual placement'};if(currentPlacement)target.placements[0]=placement;else target.placements.push(placement)}
   const old=target.records[index];record.source=old?.source||'Added by administrator';record.sourceRow=old?.sourceRow||'';record.updatedAt=new Date().toISOString();target.records[index]=record;
  },'Host saved to database',h?'Updated host record':'Added host',server);
  if(ok){render();openHost(hid)}
  }catch(error){showError(error?.message||'Unable to save this host.')}
 };
}

function rackForm(id){const r=id?rackById(id):{};modal(id?'Edit rack':'Add a rack',`<form id="rackForm"><div class="form-error" id="formError" role="alert"></div><div class="form-grid">${[['name','Rack name',r.name||''],['room','Computer room',r.room||room],['aisle','Aisle',r.aisle||'Aisle 1'],['units','Capacity (U)',r.units||42],['rj45','RJ45 ports',r.rj45||''],['fibre','Fibre ports',r.fibre||'']].map(([k,l,v])=>`<label>${l}<input name="${k}" value="${esc(v)}" ${['name','room','aisle','units'].includes(k)?'required':''} ${k==='units'?'type="number" min="1" max="60"':''} maxlength="150"></label>`).join('')}<label class="wide">Notes<textarea name="notes">${esc(r.notes||'')}</textarea></label></div></form>`,`<div class="actions">${btn('Cancel',id?'rack':'close',id||'')}<button class="btn primary" form="rackForm" type="submit">Save rack</button></div>`,'RACK ADMINISTRATION');$('#rackForm').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));for(const k of ['name','room','aisle'])v[k]=v[k].trim();v.units=Number(v.units);v.sample=false;if(!v.name||!v.room||!v.aisle){$('#formError').textContent='Rack name, room, and aisle cannot be blank.';return}if(db.racks.some(r=>r.id!==id&&r.name.toLowerCase()===v.name.toLowerCase()&&r.room===v.room&&r.aisle===v.aisle)){$('#formError').textContent='A rack with this name already exists in this room and aisle.';return}if(id&&placementList(id).some(({p})=>p.unit+p.height-1>v.units)){$('#formError').textContent='The new capacity would exclude an existing device. Move the device first.';return}const rid=id||newId();if(await transact(()=>{if(id)Object.assign(rackById(id),v);else db.racks.push({...v,id:rid,source:'Added by owner'})},'Rack saved',id?'Updated rack':'Added rack',v.name)){room=v.room;render();openRack(rid)}}}
function placementForm(hostId,rackId){modal('Assign rack position',`<form id="placementForm"><div class="form-error" id="formError" role="alert"></div><div class="warning">The map reflects documented equipment. Check physical availability before assigning a position. This adds a placement; existing placements are preserved.</div><div class="form-grid"><label class="wide">Host<select name="hostId" required>${db.hosts.filter(h=>h.type==='physical').map(h=>`<option value="${h.id}" ${h.id===hostId?'selected':''}>${esc(h.server)}</option>`).join('')}</select></label><label class="wide">Rack<select name="rackId" required>${db.racks.map(r=>`<option value="${r.id}" ${r.id===rackId?'selected':''}>${esc(roomDisplay(r.room))} / ${esc(r.aisle)} / ${esc(r.name)}</option>`).join('')}</select></label><label>Starting rack unit (bottom U)<input name="unit" type="number" min="1" max="60" value="1" required></label><label>Rack units used<input name="height" type="number" min="1" max="60" value="1" list="rackHeights" required><small class="subtle">Use 2 for a 2U server, 3 for 3U, etc.</small></label><datalist id="rackHeights"><option value="1"><option value="2"><option value="3"><option value="4"><option value="5"><option value="6"></datalist></div></form>`,`<div class="actions">${btn('Cancel','close')}<button class="btn primary" form="placementForm" type="submit">Save placement</button></div>`,'PHYSICAL PLACEMENT');$('#placementForm').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target)),r=rackById(v.rackId),h=hostById(v.hostId),u=Number(v.unit),height=Number(v.height);if(!h||h.type!=='physical'){$('#formError').textContent='Only physical hosts can be assigned to a rack.';return}if(u+height-1>r.units){$('#formError').textContent=`This device exceeds the rack’s ${r.units}U capacity.`;return}if(placementList(r.id).some(({p})=>u<p.unit+p.height&&p.unit<u+height)){$('#formError').textContent='These rack units overlap a documented device. Choose another position.';return}if(await transact(()=>h.placements.push({rackId:r.id,unit:u,height,label:h.server,source:'Rack assignment',positionBasis:'Manual placement'}),'Rack position saved','Assigned rack position',`${h.server} → ${r.name} U${u}-${u+height-1} (${height}U)`)){render();openHost(h.id)}}}
function confirmRemove(kind,id){const [hid,index]=id.split(':');const h=hostById(hid);const i=Number(index);modal('Remove '+(kind==='record'?'application record':'rack placement'),`<p class="note-paragraph">Remove ${kind==='record'?`application record ${i+1}`:`placement ${i+1}`} from <strong>${esc(h.server)}</strong>? Other application records and documented connections will be retained.</p>`,`<div class="actions">${btn('Cancel','host',hid)}${btn('Remove','confirm-remove',kind+':'+id,'danger','trash')}</div>`,'REVIEW CHANGE')}
function legacyHistory(){modal('Inventory history',db.audit.length?db.audit.map(a=>`<div class="activity-item"><strong>${esc(a.action)}</strong> · ${esc(a.object)}<small>${new Date(a.at).toLocaleString()} · ${esc(a.actorEmail||'Legacy change — identity not recorded')}</small></div>`).join(''):'<div class="empty">No changes yet. Your inventory edits will appear here.</div>',`<div class="actions">${btn('Close','close')}</div>`,'DATABASE CHANGE HISTORY')}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function exportCsv(){const headers=[...fields.map(x=>x[1])];const rows=filtered().flatMap(h=>(h.records.length?h.records:[{server:h.server}]).map(r=>[...fields.map(([k])=>r[k]||'')]));download('BSK-CMDB-export.csv','\ufeff'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast(`Exported ${rows.length} records using the current filters`)}
function help(){if(!canAdmin()){modal('About this inventory',`<p class="note-paragraph">Browse hosts, applications, computer rooms, rack placements, and documented connections from the shared CMDB inventory.</p><h3>Inventory use</h3><p class="note-paragraph">End users have read-only access. Administrators maintain host records, application assignments, rack placements, and data quality.</p>`,btn('Close','close'),'INFRASTRUCTURE INVENTORY');return}modal('Your infrastructure workspace',`<div class="settings-list"><section class="panel"><h3>Private access</h3><p>Site sharing controls who can open this private workspace. Application roles separately control who can change inventory. End users have read-only access; administrators manage inventory and access.</p></section><section class="panel"><h3>Inventory governance</h3><p>The CMDB keeps host records, application ownership, VMware details, physical rack placements, and documented LAN / SAN relationships together in one operational view. Multiple application records remain linked to the same host when needed.</p><p>Missing values remain explicit so administrators can improve data quality without inventing production information.</p></section><section class="panel"><h3>Saving your changes</h3><p><strong>Hosts, racks, and applications are saved in the shared database.</strong> Open the site from another device to see the latest saved data. Concurrent edits are checked to prevent overwriting newer changes. Export a full backup at any time; CSV export includes the CMDB fields.</p><div class="actions" style="margin-top:15px">${btn('Download full backup','backup','','','download')}${btn('Restore backup','restore','','','upload')}</div></section><section class="panel"><h3>Operational controls</h3><p>Use bulk updates, backup, restore, and change history to maintain the inventory lifecycle. Access roles are enforced by the backend, and administrator actions are recorded in the change history.</p></section></div>`,`<div class="actions">${btn('Close','close')}</div>`,'DATA & SAVING')}
function parseCSV(t){t=t.replace(/^\ufeff/,'');const rows=[];let row=[],v='',quote=false;const delimiter=t.split(/\r?\n/)[0].includes(';')&&!t.split(/\r?\n/)[0].includes(',')?';':',';for(let i=0;i<t.length;i++){const c=t[i];if(c==='"'){if(quote&&t[i+1]==='"'){v+='"';i++}else quote=!quote}else if(c===delimiter&&!quote){row.push(v);v=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&t[i+1]==='\n')i++;row.push(v);if(row.some(x=>x.trim()))rows.push(row);row=[];v=''}else v+=c}if(quote)throw Error('An unclosed quoted field was found. Please check your CSV.');row.push(v);if(row.some(x=>x.trim()))rows.push(row);return rows}
function importModal(){importDraft=null;modal('Import CMDB records',`<p class="note-paragraph">Use a CSV with the 16 original CMDB column headers. Matching server names receive additional application records. Existing data is retained. Exact duplicate records are skipped.</p><div class="actions">${btn('Download CSV template','template','','','download')}</div><input class="file-input" id="csvFile" type="file" accept=".csv,text/csv" aria-label="Choose CSV file"><div id="importError" class="form-error" role="alert"></div><div id="importPreview"></div>`,`<div class="actions">${btn('Cancel','close')}<button class="btn primary" data-action="apply-import" id="applyImport" disabled>Import records</button></div>`,'PREVIEW BEFORE IMPORT');$('#csvFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('Please use a CSV smaller than 5 MB.');const rows=parseCSV(await file.text());if(rows.length<2)throw Error('No data rows found.');const headers=rows.shift().map(x=>x.trim().toLowerCase());const aliases={ha:['high availability ?','high availability','ha'],cluster:['enclosure/vmware cluster/cluster/f5 vs','cluster / enclosure'],component:['application component','component'],installed:['date install server','install date'],owner:['infra owner','owner']};const idx=Object.fromEntries(fields.map(([k,l])=>[k,headers.findIndex(h=>[k,l.toLowerCase(),...(aliases[k]||[])].includes(h))]));if(idx.server<0)throw Error('A Server column is required.');const records=rows.map((r,i)=>({record:Object.fromEntries(fields.map(([k])=>[k,idx[k]>=0?(r[idx[k]]||'').trim():''])),row:i+2}));const invalid=records.filter(x=>!x.record.server);if(invalid.length)throw Error(`Missing server names on ${invalid.length} row(s). No records imported.`);if(records.length>5000)throw Error('Please import at most 5,000 records at a time.');importDraft=records.map(x=>x.record);$('#importError').textContent='';$('#importPreview').innerHTML=`<p><strong>${records.length} records ready.</strong> Review the first five below.</p><div class="import-preview"><table><thead><tr><th>Server</th><th>Application</th><th>Status</th></tr></thead><tbody>${importDraft.slice(0,5).map(r=>`<tr><td>${esc(r.server)}</td><td>${esc(r.application)}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div>`;$('#applyImport').disabled=false}catch(err){importDraft=null;$('#importError').textContent=err.message;$('#applyImport').disabled=true;$('#importPreview').innerHTML=''}}}
async function applyImport(){if(!importDraft)return;let added=0;const ok=await transact(()=>{for(const r of importDraft){let h=db.hosts.find(h=>h.server.toLowerCase()===r.server.toLowerCase());if(!h){h={id:newId(),server:r.server,records:[],placements:[],connections:[],sample:false,type:'unclassified',typeBasis:'Requires classification',vmware:{vcenter:'',cluster:'',esxiHost:'',vmName:''}};db.hosts.unshift(h)}if(h.records.some(old=>fields.every(([k])=>old[k]===r[k])))continue;let app=db.applications.find(a=>CmdbModel.appKey(a.name)===CmdbModel.appKey(r.application));if(!CmdbModel.absent(r.application)&&!app){app={id:newId(),name:r.application.trim(),owner:'',description:'',source:'Bulk update'};db.applications.push(app)}h.records.push({...r,applicationId:app?.id||'',source:'Bulk update',updatedAt:new Date().toISOString()});added++}},'Bulk update saved','Bulk update',`${importDraft.length} submitted rows`);if(ok){closeModal();render();toast(`${added} records imported; duplicates skipped`)}}
function restoreModal(){modal('Restore a workspace backup',`<div class="warning">Restoring replaces the database inventory, racks, and application catalog for every device. The audit trail is retained. Download a current backup first if you want to keep your edits.</div><input class="file-input" type="file" id="backupFile" accept="application/json,.json" aria-label="Choose backup JSON"><div class="form-error" id="formError" role="alert"></div><p id="restorePreview"></p>`,`<div class="actions">${btn('Cancel','help')}<button class="btn primary" id="restoreConfirm" disabled>Restore this backup</button></div>`,'REVIEW BEFORE REPLACING');let candidate;$('#backupFile').onchange=async e=>{candidate=null;$('#restoreConfirm').disabled=true;try{const f=e.target.files[0];if(!f)return;if(f.size>8e6)throw Error('Backup must be smaller than 8 MB.');const raw=JSON.parse(await f.text());const x=raw.schemaVersion===1?CmdbModel.migrate(raw):raw;if(!validDB(x))throw Error('This is not a valid BSK workspace backup.');candidate=x;$('#restorePreview').textContent=`${x.hosts.length} hosts · ${x.racks.length} racks. Ready to replace the database workspace.`;$('#formError').textContent='';$('#restoreConfirm').disabled=false}catch(err){$('#formError').textContent=err.message}};$('#restoreConfirm').onclick=async()=>{if(!candidate)return;const old=db;db=candidate;if(!await persist('Workspace restored','Restored backup',`${db.hosts.length} hosts`,'/api/admin/restore')){db=old;return}room=db.racks[0]?.room||'Salle IT 1';closeModal();render()}}
function validDB(x){try{return CmdbModel.validate(x)}catch{return false}}
function toggleRackUnitSelection(rackId,unit){
 const r=rackById(rackId);if(!r)return;
 const selected=selectedRackUnits(rackId),used=rackStats(r).used;
 if(used.has(unit)){toast('This rack unit already contains a documented device.');return}
 if(selected.includes(unit))rackUnitSelection[rackId]=selected.filter(u=>u!==unit);
 else if(!selected.length)rackUnitSelection[rackId]=[unit];
 else{
  const min=Math.min(...selected,unit),max=Math.max(...selected,unit);
  const range=Array.from({length:max-min+1},(_,i)=>min+i);
  if(range.some(u=>used.has(u))){rackUnitSelection[rackId]=[unit];toast('Selection reset because occupied units are between those positions.')}
  else rackUnitSelection[rackId]=range;
 }
 openRack(rackId);
}
function addHostFromRackSelection(rackId){
 const range=selectionRange(rackId),r=rackById(rackId);
 if(!range||!r){toast('Select one or more free rack units first.');return}
 const units=selectedRackUnits(rackId);
 if(units.length!==range.height){toast('Select contiguous rack units.');return}
 if(placementList(rackId).some(({p})=>range.unit<p.unit+p.height&&p.unit<range.unit+range.height)){toast('Selected rack units overlap a documented device.');openRack(rackId);return}
 recordForm(null,0,{rackId,unit:range.unit,height:range.height});
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;if(saving){toast('Saving to the database. Please wait.');return}const a=b.dataset.action,id=b.dataset.id;if(adminActions.has(a)&&!canAdmin()){toast('Read-only access.');return}switch(a){case'close':closeModal();break;case'host':openHost(id);break;case'rack':openRack(id);break;case'help':help();break;case'applications':applicationsModal();break;case'app-add':applicationForm();break;case'app-edit':applicationForm(id);break;case'app-delete':deleteApplication(id);break;case'app-delete-confirm':await confirmApplicationDelete(id);break;case'delete-host':deleteHost(id);break;case'delete-host-confirm':await confirmHostDelete(id);break;case'delete-rack':deleteRack(id);break;case'delete-rack-confirm':await confirmRackDelete(id);break;case'legacy':legacyModal();break;case'legacy-import':await importLegacy();break;case'reload':await reloadDatabase();break;case'go-room':location.hash='room';break;case'go-racks':location.hash='racks';break;case'room-select':room=id;rackQuery='';render();break;case'prev':page--;updateTable();break;case'next':page++;updateTable();break;case'clear-filters':qualityFilter='';typeFilter='';query='';statusFilter='';criticalFilter='';page=1;render();break;case'stat':typeFilter='';if(id==='racks'){location.hash='racks';break}qualityFilter='';query='';statusFilter=id==='prod'?'Prod':'';criticalFilter='';page=1;if(id==='high'){query='';criticalFilter='High + Very High'}render();break;case'add-host':recordForm();break;case'edit-record':{const [h,i]=id.split(':');recordForm(h,Number(i));break}case'add-record':recordForm(id,hostById(id).records.length);break;case'add-rack':rackForm();break;case'add-room':addRoomForm();break;case'edit-rack':rackForm(id);break;case'placement':placementForm(id,hostById(id).placements[0]?.rackId);break;case'rack-assign':placementForm(null,id);break;case'rack-unit-select':{const [rackId,unit]=id.split(':');toggleRackUnitSelection(rackId,Number(unit));break}case'rack-selection-add-host':addHostFromRackSelection(id);break;case'remove-record':confirmRemove('record',id);break;case'remove-placement':confirmRemove('placement',id);break;case'confirm-remove':{const [kind,hid,i]=id.split(':');const h=hostById(hid);if(await transact(()=>{h[kind==='record'?'records':'placements'].splice(Number(i),1)},'Removed successfully','Removed '+kind,h.server)){render();openHost(hid)}break}case'history':history();break;case'export':exportCsv();break;case'backup':{const response=await fetch('/api/admin/backup');const data=await response.json();if(!response.ok){toast(data.error);break}download('BSK-CMDB-backup.json',JSON.stringify(data,null,2),'application/json');toast('Full workspace backup downloaded');break;}case'restore':restoreModal();break;case'import':importModal();break;case'apply-import':applyImport();break;case'template':download('BSK-CMDB-template.csv','\ufeff'+fields.map(([,l])=>csvCell(l)).join(',')+'\r\n','text/csv');break}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal()}});
$('#dialog').addEventListener('cancel',()=>{if(lastFocus?.isConnected)setTimeout(()=>lastFocus.focus(),0)});
window.addEventListener('hashchange',()=>{if(db)navigate()});

async function reloadDatabase(){
 try{const response=await fetch(adminPage?'/api/admin/workspace':'/api/workspace',{cache:'no-store'});const result=await response.json();if(!response.ok){if(result.reauthenticationRequired){renderSiteSignIn();return false}if(adminPage&&(response.status===401||response.status===403)){lockAdmin();await enterAdmin();return false}throw Error(result.error||'Cannot load the database.');}CmdbModel.validate(result.state);db=result.state;revision=result.revision;currentRole=result.role;currentUser=result.user;updateIdentity();$('#saveState').innerHTML='<span class="dot"></span>Shared database';if(!roomNames().includes(room))room=roomNames()[0]||'';if($('#dialog').open)closeModal();navigate();return true}catch(error){toast(error.message);return false}
}
(async()=>{
 icons();
 if(adminPage){await enterAdmin();return}
 if(!await reloadDatabase()){if($('#siteSignIn'))return;$('#content').innerHTML=`<div class="empty"><h3>Unable to connect to the database</h3><p>No offline changes will be saved. Please retry.</p><br>${btn('Retry connection','reload')}</div>`;return}
 try{const saved=localStorage.getItem(KEY);if(canAdmin()&&saved&&!localStorage.getItem('bsk-legacy-reviewed')){const old=JSON.parse(saved);if(old.audit?.length){legacyData=CmdbModel.migrate(old);showLegacyBanner()}}}catch{}
})();
function applicationUsage(id){return db.hosts.filter(h=>h.records.some(r=>r.applicationId===id))}
function applicationsModal(search=''){
 const list=db.applications.filter(a=>[a.name,a.owner].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));
 modal('Application catalog',`<div class="source-banner">${icon('layers')}<span>Browse the application catalog and its documented owners.</span></div><div class="filterbar" style="padding:0 0 18px"><label class="searchbox">${icon('search')}<input id="appSearch" value="${esc(search)}" placeholder="Search applications…" aria-label="Search applications"></label>${btn('Add application','app-add','','primary','plus')}</div><p class="subtle" style="margin-bottom:14px">${list.length} applications · ${canAdmin()?'Administrator':'Catalog'}</p><div class="table-wrap"><table><thead><tr><th>Application</th><th>Owner</th><th>Hosts</th>${canAdmin()?'<th>Actions</th>':''}</tr></thead><tbody>${list.map(a=>{const count=applicationUsage(a.id).length;return `<tr><td><strong>${esc(a.name)}</strong><small class="subtle" style="display:block">${esc(a.description||'')}</small></td><td>${esc(a.owner||'—')}</td><td>${count}</td><td ${!canAdmin()?'hidden':''}><div class="actions">${btn('Edit','app-edit',a.id,'','edit')}${count?`<button class="btn" disabled title="Remove host assignments first">In use</button>`:btn('Delete','app-delete',a.id,'danger','trash')}</div></td></tr>`}).join('')||'<tr><td colspan="4">No applications match your search.</td></tr>'}</tbody></table></div>`,`<div class="actions">${btn('Close','close')}</div>`,'APPLICATION CATALOG');
 $('#appSearch').oninput=e=>{const q=e.target.value,pos=e.target.selectionStart;applicationsModal(q);$('#appSearch').focus();$('#appSearch').setSelectionRange(pos,pos)};
}
function applicationForm(id){
 const app=db.applications.find(a=>a.id===id)||{};
 modal(id?'Edit application':'Add application',`<form id="applicationForm"><div class="form-error" id="formError" role="alert"></div><div class="form-grid"><label class="wide">Application name *<input name="name" value="${esc(app.name||'')}" maxlength="1500" required></label><label class="wide">Application owner<input name="owner" value="${esc(app.owner||'')}" maxlength="1500"></label><label class="wide">Description<textarea name="description" maxlength="3000">${esc(app.description||'')}</textarea></label></div></form>`,`<div class="actions">${btn('Cancel','applications')}<button type="submit" form="applicationForm" class="btn primary">Save application</button></div>`,'ADMIN · APPLICATION DATABASE');
 $('#applicationForm').onsubmit=async e=>{
  e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const key of Object.keys(values))values[key]=values[key].trim();
  if(!values.name){$('#formError').textContent='Application name cannot be blank.';return}
  if(db.applications.some(a=>a.id!==id&&CmdbModel.appKey(a.name)===CmdbModel.appKey(values.name))){$('#formError').textContent='An application with this name already exists.';return}
  if(await transact(()=>{if(id){Object.assign(db.applications.find(a=>a.id===id),values);for(const host of db.hosts)for(const r of host.records)if(r.applicationId===id){r.originalApplication ||= r.application;r.application=values.name}}else db.applications.push({...values,id:newId(),source:'Added by owner'})},'Application saved',id?'Updated application':'Added application',values.name))applicationsModal();
 };
}
function deleteApplication(id){const app=db.applications.find(a=>a.id===id);if(!app)return;if(applicationUsage(id).length){toast('This application is in use. Remove its host assignments first.');return}modal('Delete application',`<p class="note-paragraph">Delete <strong>${esc(app.name)}</strong> from the database catalog? It is not assigned to any host.</p>`,`<div class="actions">${btn('Cancel','applications')}${btn('Delete application','app-delete-confirm',id,'danger','trash')}</div>`,'ADMIN · CONFIRM DELETION')}
async function confirmApplicationDelete(id){const app=db.applications.find(a=>a.id===id);if(!app)return;if(applicationUsage(id).length){toast('Application is in use.');return}if(await transact(()=>{db.applications=db.applications.filter(a=>a.id!==id)},'Application deleted','Deleted application',app.name))applicationsModal()}
function deleteHost(id){const h=hostById(id);if(!h)return;modal('Delete host',`<div class="warning">This deletes the host from the CMDB database. It does not contact or remove a physical server or VMware virtual machine.</div><p class="note-paragraph">Delete <strong>${esc(h.server)}</strong> and its <strong>${h.records.length}</strong> application records, <strong>${h.placements.length}</strong> rack placements, and <strong>${h.connections.length}</strong> documented network links?</p><p class="note-paragraph">The application catalog entries remain available.</p>`,`<div class="actions">${btn('Cancel','host',id)}${btn('Delete host permanently','delete-host-confirm',id,'danger','trash')}</div>`,'ADMIN · CONFIRM DELETION')}
async function confirmHostDelete(id){const h=hostById(id);if(!h)return;if(await transact(()=>{db.hosts=db.hosts.filter(h=>h.id!==id)},'Host deleted from database','Deleted host',h.server)){closeModal();render()}}
function deleteRack(id){const r=rackById(id);if(!r)return;const affected=placementList(id),hostCount=new Set(affected.map(x=>x.h.id)).size;modal('Delete rack',`<div class="warning">${hostCount?`This rack contains ${hostCount} hosts/devices in the database. Deleting it removes their placements in this rack. The host records are retained.`:'This rack has no assigned hosts.'}</div><p class="note-paragraph">Delete <strong>${esc(r.name)}</strong> in <strong>${esc(r.room)} / ${esc(r.aisle)}</strong>?</p>${affected.length?`<ul class="plain-list">${[...new Set(affected.map(x=>x.h.server))].map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}<p class="note-paragraph">Hosts with no other placements become unassigned. Historical location fields remain in their application records.</p>`,`<div class="actions">${btn('Cancel','rack',id)}${btn(hostCount?'Delete rack & unassign hosts':'Delete rack permanently','delete-rack-confirm',id,'danger','trash')}</div>`,'ADMIN · CONFIRM DELETION')}
async function confirmRackDelete(id){const r=rackById(id);if(!r)return;if(await transact(()=>{db.racks=db.racks.filter(r=>r.id!==id);for(const h of db.hosts)h.placements=h.placements.filter(p=>p.rackId!==id)},'Rack deleted; host records retained','Deleted rack',`${r.room} / ${r.aisle} / ${r.name}`)){if(!roomNames().includes(room))room=roomNames()[0]||'';closeModal();render()}}
function showLegacyBanner(){if(!legacyData)return;const content=$('#content');if(!$('#legacyBanner'))content.insertAdjacentHTML('afterbegin',`<div class="warning" id="legacyBanner">Earlier browser-only edits were found. They have not overwritten the database. ${btn('Review earlier edits','legacy')}</div>`)}
function legacyModal(){modal('Earlier browser edits',`<p class="note-paragraph">This browser contains ${legacyData.hosts.length} hosts and ${legacyData.racks.length} racks from the previous version. Your saved copy remains in this browser.</p><div class="warning">Importing replaces the database inventory and catalog with this earlier workspace. Review the shared data first if you have already made changes on another device.</div>`,`<div class="actions"><button class="btn" id="legacyDownload">Download earlier backup</button>${btn('Keep current database','close')}${btn('Import earlier workspace','legacy-import','','primary')}</div>`,'MIGRATION REVIEW');$('#legacyDownload').onclick=()=>download('BSK-earlier-browser-backup.json',JSON.stringify(legacyData,null,2),'application/json')}
async function importLegacy(){if(!legacyData)return;const snapshot=structuredClone(legacyData);if(await transact(()=>{db=snapshot},'Earlier edits saved to database','Loaded previous browser workspace',`${snapshot.hosts.length} hosts`)){localStorage.setItem('bsk-legacy-reviewed','yes');legacyData=null;closeModal();render()}}

function updateIdentity(){
 document.body.dataset.role=currentRole;
 if(canAdmin()&&!$('#adminNav'))$('nav').insertAdjacentHTML('beforeend','<a href="#admin" data-nav="admin" id="adminNav">Administration</a>');
 $('#accessLabel').textContent=canAdmin()?'Administrator':'Inventory';
 if(canAdmin()&&!$('#adminLogout'))$('.top-right').insertAdjacentHTML('beforeend','<button class="btn" id="adminLogout">Sign out</button>');
 if($('#adminLogout'))$('#adminLogout').onclick=logoutAdmin;
 $('#adminIdentity').hidden=!canAdmin();
 $('#adminHelp').hidden=!canAdmin();
 $('#currentIdentity').innerHTML=canAdmin()?`${esc(currentUser.email)}<small>Inventory administrator</small>`:'';
}
const qualityLabels={unclassified:'Unclassified hosts',owner:'Missing infrastructure owners',asset:'Missing asset IDs',placement:'Physical hosts without rack placements'};
function qualityMatches(h,key){return key==='unclassified'?h.type==='unclassified':key==='owner'?!h.records.length||h.records.some(r=>missing(r.owner)):key==='asset'?!h.records.length||h.records.some(r=>missing(r.asset)):h.type==='physical'&&!h.placements.length}
function renderApplications(){
 heading('Applications','Explore applications and their linked hosts.','APPLICATION CATALOG',btn('Add application','app-add','','primary','plus'));
 $('#content').innerHTML='<section class="panel"><div class="filterbar"><label class="searchbox">'+icon('search')+'<input id="catalogSearch" placeholder="Search application or owner…" aria-label="Search application catalog"></label></div><div id="catalogRows"></div></section>';
 const draw=()=>{const q=$('#catalogSearch').value.toLowerCase();const apps=db.applications.filter(a=>[a.name,a.owner,a.description].join(' ').toLowerCase().includes(q)).sort((a,b)=>a.name.localeCompare(b.name));$('#catalogRows').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Application</th><th>Owner</th><th>Hosts</th>${canAdmin()?'<th>Manage</th>':''}</tr></thead><tbody>${apps.map(a=>`<tr><td><button class="link-button" data-catalog-id="${esc(a.id)}">${esc(a.name)}</button><small class="subtle">${esc(a.description)}</small></td><td>${esc(a.owner||'Not documented')}</td><td>${applicationUsage(a.id).length}</td>${canAdmin()?`<td>${btn('Edit','app-edit',a.id)}${btn('Delete','app-delete',a.id)}</td>`:''}</tr>`).join('')||'<tr><td colspan="4">No matching applications.</td></tr>'}</tbody></table></div>`};draw();$('#catalogSearch').oninput=draw;
}
document.addEventListener('click',e=>{const app=e.target.closest('[data-catalog-id]');if(app){const a=db.applications.find(x=>x.id===app.dataset.catalogId);modal(a.name,`<p class="note-paragraph">${esc(a.description||'No description documented.')}</p><p>Owner: ${esc(a.owner||'Not documented')}</p><h3>Linked hosts</h3><div class="rack-equip-list">${applicationUsage(a.id).map(h=>`<div class="equip-row">${hostLink(h)}${pill(typeLabel(h.type))}</div>`).join('')||'<p>No hosts assigned.</p>'}</div>`,btn('Close','close'),'APPLICATION DETAILS')}
 const quality=e.target.closest('[data-quality]');if(quality){qualityFilter=quality.dataset.quality;query='';typeFilter='';statusFilter='';criticalFilter='';page=1;location.hash='inventory';if(view==='inventory')render()}
});
async function renderAdministration(){
 if(!canAdmin())return;
 heading('Administration','Manage application access and review inventory quality.','PRIVATE WORKSPACE',btn('Import CSV','import','','','upload')+btn('Back up inventory','backup','','','download')+btn('Restore inventory','restore','','','upload'));
 $('#content').innerHTML=`<h2>Data quality</h2><p class="note-paragraph">A host is counted when any application record lacks the field.</p><div class="quality-grid">${Object.entries(qualityLabels).map(([key,label])=>`<button class="stat" data-quality="${key}"><span class="stat-value">${db.hosts.filter(h=>qualityMatches(h,key)).length}</span><span>${label}</span><small>View affected hosts →</small></button>`).join('')}</div><section class="panel"><div class="panel-title"><div><h2>User access</h2><p>Only authenticated visitors appear here after their first sign-in. New visitors receive read-only access. Site sharing is managed separately.</p></div></div><div id="usersPanel" class="admin-section">Loading users…</div></section><section class="panel admin-history"><div class="panel-title"><div><h2>Inventory change history</h2><p>Recorded on the server with the authenticated identity and before/after values.</p></div>${btn('View history','history','','','clock')}</div></section>`;
 try{const response=await fetch('/api/admin/users');const data=await response.json();if(!response.ok)throw Error(data.error);if(view!=='admin')return;
 $('#usersPanel').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Authenticated user</th><th>Application role</th><th>Access</th><th>Save</th></tr></thead><tbody>${data.users.map((u,i)=>`<tr><td>${esc(u.email)}${u.id===currentUser.id?' <span class="pill">You</span>':''}<small class="subtle identity-id">${esc(u.id)}</small></td><td><select aria-label="Role for ${esc(u.email)}" id="role-${i}"><option value="reader" ${u.role==='reader'?'selected':''}>End user</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrator</option></select></td><td><label><input type="checkbox" id="enabled-${i}" ${u.enabled?'checked':''} aria-label="Enable access for ${esc(u.email)}"> Enabled</label></td><td><button class="btn" data-save-user="${i}">Save access</button></td></tr>`).join('')}</tbody></table></div><p class="note-paragraph">The last enabled administrator cannot be disabled or demoted. Disabling application access takes effect on the next API request.</p>`;
 $$('[data-save-user]').forEach(button=>button.onclick=async()=>{const i=Number(button.dataset.saveUser),u=data.users[i];button.disabled=true;try{const response=await fetch('/api/admin/users',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:u.id,version:u.version,role:$('#role-'+i).value,enabled:$('#enabled-'+i).checked})});const result=await response.json();if(!response.ok)throw Error(result.error);toast('Application access updated');await reloadDatabase()}catch(error){toast(error.message);button.disabled=false}});
 }catch(error){if($('#usersPanel'))$('#usersPanel').textContent=error.message}
}
async function history(offset=0){
 modal('Inventory change history','<p>Loading changes…</p>',btn('Close','close'),'ADMINISTRATION');
 try{const response=await fetch('/api/admin/history?offset='+offset);const data=await response.json();if(!response.ok)throw Error(data.error);
 const events=data.events.map(event=>`<article class="activity-item"><strong>${esc(event.action)}</strong><small>${esc(new Date(event.at).toLocaleString())} · ${esc(event.actor_email)}</small>${Array.isArray(event.details)?event.details.map(d=>`<details><summary>${esc(d.action)} ${esc(d.kind)} · ${esc(d.name||d.id)}${d.fields?' · '+esc(d.fields.join(', ')):''}</summary><div class="change-comparison"><div><strong>Before</strong><pre>${esc(JSON.stringify(d.before,null,2))}</pre></div><div><strong>After</strong><pre>${esc(JSON.stringify(d.after,null,2))}</pre></div></div></details>`).join(''):`<pre>${esc(JSON.stringify(event.details,null,2))}</pre>`}</article>`).join('');
 modal('Inventory change history',events||'<p>No attributed changes yet.</p>',`<div class="actions">${offset?'<button class="btn" id="historyPrev">Previous</button>':''}${data.hasMore?'<button class="btn" id="historyNext">Next</button>':''}<button class="btn" id="legacyHistory">Earlier inventory history</button>${btn('Close','close')}</div>`,'ADMINISTRATION');if($('#historyPrev'))$('#historyPrev').onclick=()=>history(offset-50);if($('#historyNext'))$('#historyNext').onclick=()=>history(offset+50);$('#legacyHistory').onclick=legacyHistory;
 }catch(error){modal('Inventory change history',`<p>${esc(error.message)}</p>`,btn('Close','close'))}
}

function lockAdmin(){
 currentRole='reader';db=null;legacyData=null;
 if($('#dialog').open)closeModal();
 $('#adminNav')?.remove();$('#adminLogout')?.remove();
 $('#accessLabel').textContent='Sign in';
 $('#currentIdentity').textContent='Private workspace';
 $('#navCount').textContent='';
 $('#pageActions').innerHTML='';$('#content').innerHTML='';
}
async function enterAdmin(){
 try{
  const response=await fetch('/api/admin/auth/status',{cache:'no-store'}),result=await response.json();
  if(!response.ok){if(result.reauthenticationRequired){renderSiteSignIn();return}lockAdmin();heading('Access unavailable','This account cannot open this workspace.','PRIVATE WORKSPACE','');$('#content').innerHTML='<p><a href="/">Return to inventory</a></p>';return}
  if(result.authenticated){await reloadDatabase();return}
  renderAdminLogin(result.setupRequired);
 }catch(error){lockAdmin();heading('Unable to connect','Please retry the connection.','PRIVATE WORKSPACE','');$('#content').innerHTML='<button class="btn" id="retryLogin">Retry</button>';$('#retryLogin').onclick=enterAdmin}
}
function renderAdminLogin(setup=false){
 lockAdmin();
 heading(setup?'Set up your login':'Administration sign in',setup?'Choose a username and password for your account.':'Enter your username and password to continue.','BSK INFRASTRUCTURE','');
 $('#content').innerHTML=`<section class="panel login-panel"><form id="adminLogin"><div class="form-error" id="loginError" role="alert"></div><label>Username<input name="username" autocomplete="username" required minlength="3" maxlength="100" pattern="[A-Za-z0-9._@-]+" autocapitalize="none" spellcheck="false"></label><label>Password<input name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" required ${setup?'minlength="14"':''} maxlength="256"></label>${setup?'<label>Confirm password<input name="confirmation" type="password" autocomplete="new-password" required minlength="14" maxlength="256"></label><p class="note-paragraph">Use at least 14 characters. Your credentials are linked to your private Site account.</p>':''}<button type="submit" class="btn primary">${setup?'Create login':'Sign in'}</button><a href="/">Return to inventory</a></form></section>`;
 $('#adminLogin').onsubmit=async e=>{
  e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form)),errorBox=$('#loginError'),button=form.querySelector('[type=submit]');
  if(setup&&values.password!==values.confirmation){errorBox.textContent='Passwords do not match.';return}
  button.disabled=true;errorBox.textContent='';
  try{
   const response=await fetch('/api/admin/auth/'+(setup?'setup':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:values.username,password:values.password})});
   const result=await response.json();if(!response.ok)throw Error(result.error||'Unable to sign in.');
   form.reset();
   if(setup){renderAdminLogin(false);toast('Login created. Sign in with your username and password.')}else await reloadDatabase();
  }catch(error){errorBox.textContent=error.message;form.querySelector('[name=password]').value='';button.disabled=false}
 };
}
async function logoutAdmin(){
 try{const response=await fetch('/api/admin/auth/logout',{method:'POST'});if(!response.ok)throw Error('Unable to sign out. Please retry.');lockAdmin();renderAdminLogin(false)}catch(error){toast(error.message)}
}

function renderSiteSignIn(){
 lockAdmin();
 heading('Sign in to continue','Verify your account to open the private inventory.','','');
 const returnTo=adminPage?'/admin':'/';
 $('#content').innerHTML=`<section class="panel login-panel"><p>Your session needs to be renewed.</p><a id="siteSignIn" class="btn primary" target="_top" href="/signin-with-chatgpt?return_to=${encodeURIComponent(returnTo)}">Sign in with ChatGPT</a><p class="note-paragraph">If this message returns after sign-in, the Site identity service is unavailable. Please retry later.</p></section>`;
}
